\pard\fi0\li0\ql\ri0\sb0\sa120\itap0 \plain \f0\fs24  {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 339 Blatt}}\plain \f1\lang1033\fs24  \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 19 x 15,5}}\plain \f1\lang1033\fs24  \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 vermutlich Prag}}\plain \f1\lang1033\fs24  \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 um 1693\endash 1700}}}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa60\itap0 \plain \f0\fs24  \plain \f1\lang1033\fs20  Schrift schl\u228 \'e4gt durch, Schriftspiegel und {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Papier}}\plain \f1\lang1033\fs20   verbr\u228 \'e4unt, R\u252 \'fccken defekt, Leder br\u252 \'fcchig. 339 gez\u228 \'e4hlte Bl\u228 \'e4tter, plus ein Blatt ungez\u228 \'e4hlter Vorsatz. Alte Lagenz\u228 \'e4hlung in den ersten 24 Lagen jeweils oben rechts auf dem ersten Blatt einer Lage. Moderne Bleistiftfoliierung in Zehnerschritten. Zwischen fol. 306 und 307 und 316 und 317 Schaltzettel eingebunden, gez\u228 \'e4hlt 306a und 316a. Vermutlich mehrere H\u228 \'e4nde, darunter eine vermutlich die des {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Johann Joseph Ignatz Freischlag}}\plain \f1\lang1033\fs20, von dem auch die Handschriften {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M I 155}}\plain \f1\lang1033\fs20, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M I 156}}\plain \f1\lang1033\fs20, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M I 157}}\plain \f1\lang1033\fs20, {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M I 158}}\plain \f1\lang1033\fs20, {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M I 159}}\plain \f1\lang1033\fs20, {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M II 19}}\plain \f1\lang1033\fs20, {\field{\*\fldinst HYPERLINK "hida://5007[6].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M II 29}}\plain \f1\lang1033\fs20, {\field{\*\fldinst HYPERLINK "hida://5007[7].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M II 59}}\plain \f1\lang1033\fs20  stammen; zu Freischlag s. M I 155. 
\par \pard\fi0\li0\ql\ri0\sb0\sa60\itap0 182\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  : Vermerk eines der anderen Schreiber \u252 \'fcber Johannes Freischlag. \plain \f1\i\lang1033\fs20  Joannes freisak est mente captus in Aprili ita vehementer, ut eum Majus licet amenissimus, liberare non potuerit..\plain \f1\lang1033\fs20  306a und 316a: Vermerk \u252 \'fcber den Vorbesitz des Johann Joseph Ignatz Freischlag, wegen der Bindung schwer lesbar. }

